// ATOM2_W06 · CRM Sync · biblioteca (cada Code node do workflow cola esta lib + uma linha de retorno).
// Fonte: 03_FUNIS_PIPEDRIVE.md §3 (entrada do funil Prospecção Ativa só com QA aprovado) e Fluxo do Funil v1.0 §7.
// Idempotente: procura o negócio pelo campo ATOM · company_id antes de criar; organização por nome exato.
// Itens de plano { method, url, body } vão para um nó HTTP Request; o que já existe vira GET inofensivo.
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };
const cfgMapa = (rows) => Object.fromEntries((rows || []).filter((r) => r && r.chave).map((r) => [r.chave, String(r.valor ?? '')]));
const dados = (r) => (r && r.data) || null;
const hoje = () => new Date().toISOString().slice(0, 10);
function selecionar(empresas, auditorias, achados, cfgRows, limite) {
  const cfg = cfgMapa(cfgRows);
  const faltando = ['PD2_PIPE_OUT_ID', 'PD2_STAGE_OUT_PRONTO_ID', 'PD2_FIELD_COMPANY_ID'].filter((k) => !cfg[k]);
  if (faltando.length) throw new Error('Configuração do Pipedrive ausente: ' + faltando.join(', ') + ' (rode ATOM2_06_Setup_Pipedrive)');
  const out = [];
  for (const e of empresas || []) {
    if (!e || e.funil_etapa !== 'F3' || e.pipedrive_deal_id || e.opt_out === true || String(e.opt_out) === 'true') continue;
    const aud = (auditorias || []).filter((a) => a && a.company_id === e.company_id && a.qa_status === 'aprovado').sort((a, b) => String(b.qa_em).localeCompare(String(a.qa_em)))[0];
    if (!aud || !aud.mensagem_aprovada) continue;
    const doAud = (achados || []).filter((f) => f && f.audit_id === aud.audit_id);
    const principal = doAud.find((f) => f.finding_id === aud.principal_finding_id) || null;
    out.push({ empresa: e, auditoria: aud, principal, resumo: doAud.filter((f) => f.usado_em === 'principal' || f.usado_em === 'resumo'), cfg });
  }
  return out.slice(0, Math.max(1, Math.min(50, Number(limite) || 20)));
}
return selecionar($('Ler empresas F3').all().map((i) => i.json), $('Ler auditorias aprovadas').all().map((i) => i.json), $('Ler achados aprovados').all().map((i) => i.json), $('Ler configuração').all().map((i) => i.json), 20).map((j) => ({ json: j }));

// ATOM2_W06 · Plano organização (trecho de n8n/code/w06_sync.js).
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };
const dados = (r) => (r && r.data) || null;
function planoOrg(ctx, buscaDeal, buscaOrg) {
  const deal = ((dados(buscaDeal) || {}).items || [])[0];
  if (deal) return { ...NOOP, ref: 'org:negocio_existe' };
  const org = ((dados(buscaOrg) || {}).items || []).map((i) => i.item).find((o) => o && String(o.name).trim().toLowerCase() === String(ctx.empresa.nome).trim().toLowerCase());
  if (org) return { ...NOOP, ref: 'org:existe' };
  const e = ctx.empresa;
  const body = { name: e.nome, visible_to: 3 };
  const c = ctx.cfg;
  if (c.PD_ORG_TELEFONE_KEY && e.telefone) body[c.PD_ORG_TELEFONE_KEY] = '+' + String(e.telefone).replace(/\D/g, '');
  if (c.PD_ORG_CIDADE_KEY && e.cidade) body[c.PD_ORG_CIDADE_KEY] = e.cidade;
  if (c.PD_ORG_UF_KEY && e.uf) body[c.PD_ORG_UF_KEY] = e.uf;
  return { method: 'POST', url: API + '/organizations', body, ref: 'org:criar' };
}
const ctx = $('Uma empresa por vez').first().json;
return [{ json: planoOrg(ctx, $('Buscar negócio').first().json, $('Buscar organização').first().json) }];

// ATOM2_W06 · Plano negócio (trecho de n8n/code/w06_sync.js).
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };
const dados = (r) => (r && r.data) || null;
// Resposta de uma etapa só conta se o plano foi POST (o GET inofensivo /users/me devolve o id do usuário!).
const respSe = (plano, resp) => (plano && plano.method === 'POST' ? resp : {});
const orgId = (buscaOrg, respOrg, ctx) => {
  const criada = dados(respOrg);
  if (criada && criada.id && respOrg && respOrg.success) return criada.id;
  const org = ((dados(buscaOrg) || {}).items || []).map((i) => i.item).find((o) => o && String(o.name).trim().toLowerCase() === String(ctx.empresa.nome).trim().toLowerCase());
  return org ? org.id : null;
};
function corpoNegocio(ctx, org) {
  const { empresa: e, auditoria: a, principal: p, cfg } = ctx;
  const f = (k) => cfg['PD2_FIELD_' + k];
  const opt = (k, slug) => cfg['PD2_OPT_' + k + '_' + slug];
  const body = { title: e.nome + ' — Prospecção ativa', org_id: org || undefined, pipeline_id: Number(cfg.PD2_PIPE_OUT_ID), stage_id: Number(cfg.PD2_STAGE_OUT_PRONTO_ID), status: 'open', visible_to: 3 };
  const set = (k, v) => { if (k && v !== undefined && v !== null && v !== '') body[k] = v; };
  set(f('ORIGEM'), opt('ORIGEM', 'PROSPECCAO_ATIVA') && Number(opt('ORIGEM', 'PROSPECCAO_ATIVA')));
  set(f('CANAL'), opt('CANAL', 'WHATSAPP_N_2') && Number(opt('CANAL', 'WHATSAPP_N_2')));
  set(f('OFERTA'), opt('OFERTA', 'CLINICA_COMPLETA') && Number(opt('OFERTA', 'CLINICA_COMPLETA')));
  set(f('COMPANY_ID'), e.company_id);
  set(f('AUDIT_ID'), a.audit_id);
  set(f('FINDING_ID'), p && p.finding_id);
  set(f('EVIDENCE_URL'), p && p.source_url);
  set(f('EVIDENCE_DATE'), p && String(p.observed_at || '').slice(0, 10));
  set(f('SCORE'), a.score != null ? Number(a.score) : null);
  set(f('FAIXA'), a.faixa && opt('FAIXA', a.faixa) && Number(opt('FAIXA', a.faixa)));
  set(f('QA_STATUS'), opt('QA_STATUS', 'APROVADO') && Number(opt('QA_STATUS', 'APROVADO')));
  set(f('PERMISSAO'), opt('PERMISSAO', e.telefone ? 'AUTORIZADA' : 'NAO_AVALIADA') && Number(opt('PERMISSAO', e.telefone ? 'AUTORIZADA' : 'NAO_AVALIADA')));
  set(f('TOQUE'), opt('TOQUE', 'D1') && Number(opt('TOQUE', 'D1')));
  set(f('PROXIMA_ACAO'), 'Enviar 1º contato (recepção) pela fila W07');
  if (cfg.PD_DEAL_DOMINIO_KEY) set(cfg.PD_DEAL_DOMINIO_KEY, e.dominio);
  if (cfg.PD_DEAL_NICHO_KEY) set(cfg.PD_DEAL_NICHO_KEY, { dental: 'Odontologia', medical: 'Clínica médica', tires: 'Pneus' }[e.vertical] || e.vertical);
  return body;
}
function planoNegocio(ctx, buscaDeal, buscaOrg, respOrg) {
  const deal = ((dados(buscaDeal) || {}).items || [])[0];
  if (deal) return { ...NOOP, ref: 'negocio:existe', existente: deal.item.id };
  return { method: 'POST', url: API + '/deals', body: corpoNegocio(ctx, orgId(buscaOrg, respOrg, ctx)), ref: 'negocio:criar' };
}
const ctx = $('Uma empresa por vez').first().json;
const ro = respSe($('Plano organização').first().json, $('Aplicar organização').first().json);
return [{ json: planoNegocio(ctx, $('Buscar negócio').first().json, $('Buscar organização').first().json, ro) }];

// ATOM2_W06 · Plano nota (trecho de n8n/code/w06_sync.js).
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };
const dados = (r) => (r && r.data) || null;
const respSe = (plano, resp) => (plano && plano.method === 'POST' ? resp : {});
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const dealId = (buscaDeal, respDeal) => {
  const d = dados(respDeal);
  if (d && d.id && respDeal.success) return { id: d.id, criado: true };
  const ex = ((dados(buscaDeal) || {}).items || [])[0];
  return ex ? { id: ex.item.id, criado: false } : { id: null, criado: false };
};
function corpoNota(ctx, deal) {
  const { empresa: e, auditoria: a, resumo } = ctx;
  const linhas = resumo.map((f) => `<li><b>${esc(f.claim)}</b><br>Evidência: ${esc(f.evidence)}<br>Fonte: <a href="${esc(f.source_url)}">${esc(f.source_url)}</a> (${esc(String(f.observed_at).slice(0, 10))}, confiança ${Math.round((f.confidence || 0) * 100)}%)</li>`).join('');
  return { deal_id: deal, pinned_to_deal_flag: 1, content: `<p><b>Diagnóstico N1</b> · ${esc(a.audit_id)} · score ${esc(a.score)} (faixa ${esc(a.faixa)}) · QA aprovado por ${esc(a.qa_por)} em ${esc(String(a.qa_em).slice(0, 10))}</p><ul>${linhas}</ul><p><b>1º contato (recepção):</b><br>${esc(a.mensagem_aprovada)}</p><p><b>Mensagem ao decisor:</b><br>${esc(a.mensagem_decisor)}</p><p>Site: ${esc(e.dominio)} · Fonte da empresa: ${esc(e.fonte_url)} (${esc(String(e.fonte_data).slice(0, 10))})</p><p><i>Regra: nenhum agente fala de preço antes da proposta enviada.</i></p>` };
}
function planoNota(ctx, buscaDeal, respDeal) {
  const d = dealId(buscaDeal, respDeal);
  return d.criado ? { method: 'POST', url: API + '/notes', body: corpoNota(ctx, d.id), ref: 'nota:criar' } : { ...NOOP, ref: 'nota:pular' };
}
const ctx = $('Uma empresa por vez').first().json;
const rd = respSe($('Plano negócio').first().json, $('Aplicar negócio').first().json);
return [{ json: planoNota(ctx, $('Buscar negócio').first().json, rd) }];

// ATOM2_W06 · Registros (trecho de n8n/code/w06_sync.js).
const dados = (r) => (r && r.data) || null;
const respSe = (plano, resp) => (plano && plano.method === 'POST' ? resp : {});
// 1º contato na janela da manhã (9h–11h de São Paulo, dia útil): fora dela, agenda para o próximo dia útil às 9h.
const FERIADOS = ['2026-01-01', '2026-02-16', '2026-02-17', '2026-04-03', '2026-04-21', '2026-05-01', '2026-06-04', '2026-09-07', '2026-10-12', '2026-11-02', '2026-11-15', '2026-11-20', '2026-12-25',
  '2027-01-01', '2027-02-08', '2027-02-09', '2027-03-26', '2027-04-21', '2027-05-01', '2027-05-27', '2027-09-07', '2027-10-12', '2027-11-02', '2027-11-15', '2027-11-20', '2027-12-25'];
const util = (dia) => { const w = new Date(dia + 'T12:00:00Z').getUTCDay(); return w !== 0 && w !== 6 && !FERIADOS.includes(dia); };
function janelaD1(agoraISO) {
  const sp = new Date(new Date(agoraISO).getTime() - 3 * 3600 * 1000);
  let dia = sp.toISOString().slice(0, 10);
  const h = sp.getUTCHours() + sp.getUTCMinutes() / 60;
  if (util(dia) && h >= 9 && h < 11) return agoraISO;
  if (!(util(dia) && h < 9)) { do { const d = new Date(dia + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + 1); dia = d.toISOString().slice(0, 10); } while (!util(dia)); }
  return dia + 'T12:00:00.000Z';
}

const orgId = (buscaOrg, respOrg, ctx) => {
  const criada = dados(respOrg);
  if (criada && criada.id && respOrg && respOrg.success) return criada.id;
  const org = ((dados(buscaOrg) || {}).items || []).map((i) => i.item).find((o) => o && String(o.name).trim().toLowerCase() === String(ctx.empresa.nome).trim().toLowerCase());
  return org ? org.id : null;
};

const dealId = (buscaDeal, respDeal) => {
  const d = dados(respDeal);
  if (d && d.id && respDeal.success) return { id: d.id, criado: true };
  const ex = ((dados(buscaDeal) || {}).items || [])[0];
  return ex ? { id: ex.item.id, criado: false } : { id: null, criado: false };
};

// 5) Registros internos: empresa (F4 + IDs), cadência D1 e evento. Sem negócio = falha documentada.
// A cadência nasce sempre que o negócio ainda não tem uma (inclusive se o negócio já existia de uma rodada que falhou no meio).
function registros(ctx, buscaDeal, respDeal, buscaOrg, respOrg, cadencias, agoraISO) {
  const agora = agoraISO || new Date().toISOString();
  const d = dealId(buscaDeal, respDeal);
  const e = ctx.empresa;
  const ev = (tipo, motivo, dadosEv) => ({ destino: 'evento', evento: { event_id: 'e_w06_' + e.company_id + '_' + tipo.toLowerCase(), correlation_id: ctx.auditoria.audit_id, company_id: e.company_id, workflow: 'ATOM2_W06', tipo, motivo, dados: JSON.stringify(dadosEv || {}), ocorrido_em: agora } });
  if (!d.id) return [ev('CRM_FALHA', 'negócio não criado', { resposta: respDeal && (respDeal.error || respDeal.error_info) || null })];
  const out = [
    { destino: 'empresa', linha: { company_id: e.company_id, pipedrive_deal_id: String(d.id), pipedrive_org_id: String(orgId(buscaOrg, respOrg, ctx) || ''), funil_etapa: 'F4', status_motivo: 'No Pipedrive (Prospecção ativa) aguardando 1º contato', atualizado_em: agora } }
  ];
  const temCadencia = (cadencias || []).some((c) => c && String(c.deal_id) === String(d.id));
  if (!temCadencia) out.push({ destino: 'cadencia', linha: { company_id: e.company_id, deal_id: String(d.id), funil: 'OUT', passo_atual: '', proximo_passo: 'D1', proximo_em: janelaD1(agora), status: 'ativa', envios: 0, iniciado_em: agora, atualizado_em: agora } });
  out.push(ev(d.criado ? 'CRM_CRIADO' : 'CRM_JA_EXISTIA', 'deal ' + d.id, { deal_id: d.id }));
  return out;
}

const ctx = $('Uma empresa por vez').first().json;
const ro = respSe($('Plano organização').first().json, $('Aplicar organização').first().json);
const rd = respSe($('Plano negócio').first().json, $('Aplicar negócio').first().json);
return registros(ctx, $('Buscar negócio').first().json, rd, $('Buscar organização').first().json, ro, $('Ler cadências').all().map((i) => i.json)).map((j) => ({ json: j }));
